/** Local clock time (HH:MM) for a wall-clock nanosecond timestamp. */
export const clockTime = (ns: number): string =>
  new Date(ns / 1e6).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });

// SwitchReason on the wire to the words the contract allows; the two configuration faults read as
// a service error to the user.
const SWITCH_REASONS: Record<string, string> = {
  rate_limit: "rate limit",
  out_of_quota: "out of quota",
  service_error: "service error",
  timeout: "timeout",
  unreachable: "unreachable",
  bad_key: "service error",
  config_error: "service error",
};

export const switchReasonText = (reason: string): string =>
  SWITCH_REASONS[reason] ?? "service error";

// The hub stores a system row's text as space-separated key=value facts (hub/projections.py); the
// store writes live rows in the same shape, so snapshot and live rows render identically.
function parseFacts(facts: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const part of facts.split(" ")) {
    const i = part.indexOf("=");
    if (i > 0) out[part.slice(0, i)] = part.slice(i + 1);
  }
  return out;
}

/** The sentence a system row shows. `label` turns a provider id into its display name. */
export function systemRowText(
  systemEvent: string | null | undefined,
  facts: string,
  label: (providerId: string) => string = (id) => id,
): string {
  if (systemEvent === "llm.exhausted") return copy.noModelReachable;
  if (systemEvent === "llm.blocked_privacy") return copy.privacyBlock;
  if (systemEvent === "llm.switch") {
    const f = parseFacts(facts);
    const to = f.to?.split("/")[0];
    if (f.role && to && f.reason) {
      return copy.switched(f.role, label(to), switchReasonText(f.reason));
    }
  }
  return facts;
}
